import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const AdmInfCurso = () => {
  const { id } = useParams();
  const [curso, setCurso] = useState({
    nome: "",
    nivel: "",
    periodo: "",
    area: "",
    professor: "",
    alunos: [],
  });
  const [alunos, setAlunos] = useState([]);
  const [professores, setProfessores] = useState([]);
  const [editMode, setEditMode] = useState(false);

  useEffect(() => {
    const fetchCurso = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/cursos/${id}`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setCurso(dados);
        }
      } catch (error) {
        console.error("Erro na requisição:", error);
      }
    };

    const fetchAlunos = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/alunos`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setAlunos(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de alunos:", error);
      }
    };

    const fetchProfessores = async () => {
      try {
        const resposta = await fetch(`http://localhost:5000/professores`);
        if (resposta.ok) {
          const dados = await resposta.json();
          setProfessores(dados);
        }
      } catch (error) {
        console.error("Erro na requisição de professores:", error);
      }
    };

    fetchCurso();
    fetchAlunos();
    fetchProfessores();
  }, [id]);

  const handleAlunoCheckboxChange = (e) => {
    const aluno = e.target.value;
    setCurso((prevCurso) => {
      const alunos = e.target.checked
        ? [...prevCurso.alunos, aluno]
        : prevCurso.alunos.filter((aluno) => aluno !== aluno);
      return { ...prevCurso, alunos };
    });
  };

  return (
    <div className="container mt-4">
      <h1 className="text-primary text-center">EducaWeb</h1>
      <div className="d-flex justify-content-between align-items-center mt-4">
        <h2>{curso.nome}</h2>
        {!editMode && (
          <button className="btn btn-primary" onClick={() => setEditMode(true)}>
            Editar
          </button>
        )}
      </div>

      <div className="d-flex bg-white p-4 rounded shadow mt-3">
        <div className="w-50 pe-4 border-end">
          <h4 className="fw-bold">Informações do Curso</h4>
          <p>
            <strong>{curso.nome}</strong>
          </p>
          <p>{curso.nivel}</p>
          <p>{curso.periodo}</p>
          <p>{curso.area}</p>
        </div>

        <div className="w-50 ps-4">
          <div className="mb-3">
            <label className="fw-bold">Professor</label>
            <select
              className="form-control"
              name="professor"
              value={curso.professor}
              onChange={(e) =>
                setCurso({ ...curso, professor: e.target.value })
              }
              disabled={!editMode}
            >
              <option value="">Selecione um professor</option>
              {professores.map((professor) => (
                <option key={professor.id} value={professor.nome}>
                  {professor.nome}
                </option>
              ))}
            </select>
          </div>

          <label className="fw-bold">Alunos</label>
          <div className="mb-2">
            {alunos.map((aluno) => (
              <div key={aluno.id} className="form-check">
                <input
                  className="form-check-input"
                  type="checkbox"
                  value={aluno.nome}
                  checked={curso.alunos.includes(aluno.nome)}
                  onChange={handleAlunoCheckboxChange}
                  disabled={!editMode}
                />
                <label className="form-check-label">{aluno.nome}</label>
              </div>
            ))}
          </div>

          {editMode && (
            <div className="d-flex justify-content-between mt-3">
              <button
                className="btn btn-danger"
                onClick={() => setEditMode(false)}
              >
                Cancelar
              </button>
              <button
                className="btn btn-primary"
                onClick={() => setEditMode(false)}
              >
                Salvar
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AdmInfCurso;
